import itertools
import json
import os
import re
import socket
import sys
import threading
import time
import traceback
import types
from collections import defaultdict
from typing import Any

import humps

from artifact_tool_v2.rpc.types import ArtifactHandle, ArtifactOperation, ArtifactOperations


class TransportError(RuntimeError):
    """Transport-level failures (socket closed, parse issues, etc.)."""


class RemoteError(RuntimeError):
    """Application-level failures originating from the Node daemon."""

    def __init__(
        self, message: str, *, name: str = "Error", code: str = "JS_ERROR", stack: str | None = None
    ):
        super().__init__(message)
        self.name = name
        self.code = code
        self.stack = stack

    def __str__(self) -> str:
        base = super().__str__()
        if self.stack and os.environ.get("DEBUG"):
            return f"{base}\n--- Remote stack ---\n{self.stack}"
        return base


_ORIGINAL_EXCEPTHOOK = sys.excepthook


def _remote_error_excepthook(
    exc_type: type[BaseException], exc: BaseException, tb: types.TracebackType | None
) -> None:
    if isinstance(exc, RemoteError):
        tb_exc = traceback.TracebackException.from_exception(exc, capture_locals=False)
        filtered = [
            frame
            for frame in tb_exc.stack
            if "artifact_tool_v2/rpc/" not in frame.filename.replace("\\", "/")
        ]
        tb_exc.stack = traceback.StackSummary.from_list(filtered)
        print("Traceback (most recent call last):", file=sys.stderr)
        for line in tb_exc.stack.format():
            print(line, file=sys.stderr, end="")
        for line in tb_exc.format_exception_only():
            print(line, file=sys.stderr, end="")
        return

    _ORIGINAL_EXCEPTHOOK(exc_type, exc, tb)


if sys.excepthook is not _remote_error_excepthook:
    sys.excepthook = _remote_error_excepthook


_REMOTE_NAME_PATTERN = re.compile(r"\b(Method|Attribute)\s+([A-Za-z_][A-Za-z0-9_]*)\b")


def _normalize_remote_message(message: str) -> str:
    def _replace(match: re.Match[str]) -> str:
        kind = match.group(1)
        name = match.group(2)
        return f"{kind} {humps.decamelize(name)}"

    return _REMOTE_NAME_PATTERN.sub(_replace, message)


class JsonRpcClient:
    """
    Thread-safe JSON-RPC client using newline-delimited framing over a local socket or TCP socket.

    Assumes request/response ordering per connection; we serialize sends with a lock.
    """

    def __init__(self, socket_path: str):
        self.socket_path = socket_path
        self.artifact_operations: defaultdict[str, list[ArtifactOperation]] = defaultdict(list)
        self.artifact_crdt_updates_v2: defaultdict[str, list[str]] = defaultdict(list)

        self._id_counter = itertools.count(1)
        self._lock = threading.Lock()
        self._buffer = b""

        if socket_path.startswith("tcp://"):
            _, _, address = socket_path.partition("tcp://")
            host, _, port = address.partition(":")
            self._sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self._sock.connect((host, int(port)))
        else:
            self._sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
            self._sock.connect(socket_path)

    def close(self) -> None:
        try:
            self._sock.close()
        except Exception:
            pass

    def _recv_one_line(self) -> bytes:
        while b"\n" not in self._buffer:
            chunk = self._sock.recv(4096)
            if not chunk:
                raise TransportError("RPC connection closed by peer")
            self._buffer += chunk

        line, self._buffer = self._buffer.split(b"\n", 1)
        return line

    def call(
        self,
        method: str,
        params: dict[str, Any],
        *,
        timeout_s: float | None = None,
    ) -> Any:
        req_id = next(self._id_counter)
        request = {
            "jsonrpc": "2.0",
            "id": req_id,
            "method": method,
            "params": params,
        }

        payload = json.dumps(request).encode("utf-8") + b"\n"

        deadline = time.monotonic() + timeout_s if timeout_s is not None else None
        if timeout_s is None:
            self._lock.acquire()
        elif not self._lock.acquire(timeout=timeout_s):
            raise TransportError("RPC transport error: timed out waiting for client lock")

        try:
            previous_timeout = self._sock.gettimeout() if timeout_s is not None else None
            try:
                if timeout_s is not None:
                    assert deadline is not None
                    self._sock.settimeout(max(deadline - time.monotonic(), 0.0))
                self._sock.sendall(payload)
                raw = self._recv_one_line()
            except OSError as e:
                raise TransportError(f"RPC transport error: {e}") from e
            finally:
                if timeout_s is not None:
                    try:
                        self._sock.settimeout(previous_timeout)
                    except OSError:
                        pass
        finally:
            self._lock.release()

        try:
            resp = json.loads(raw.decode("utf-8"))
        except Exception as e:
            raise TransportError(f"Invalid JSON-RPC response: {raw!r}") from e

        if "error" in resp:
            err = resp["error"]
            data = err.get("data") or {}
            # Node side: { code: -32000, message: "Server error", data: {name,message,stack,code} }
            remote = data if isinstance(data, dict) else {}
            message = remote.get("message") or err.get("message") or "Remote error"
            raise RemoteError(
                _normalize_remote_message(message),
                name=remote.get("name", "Error"),
                code=remote.get("code", "JS_ERROR"),
                stack=remote.get("stack"),
            )

        if "operations" in resp:
            operations = ArtifactOperations.model_validate(resp["operations"])
            self._handle_operations(operations)

        return resp.get("result")

    def _handle_operations(self, operations: ArtifactOperations) -> None:
        artifact_handle = operations.artifactHandle.objectId
        self.artifact_operations[artifact_handle].extend(operations.operations)
        if operations.crdtUpdateV2 is None:
            return
        self.artifact_crdt_updates_v2[artifact_handle].append(operations.crdtUpdateV2)

    def record_artifact_operation(self, artifact_handle: str, operation: ArtifactOperation) -> None:
        self._handle_operations(
            ArtifactOperations(
                artifactHandle=ArtifactHandle(objectId=artifact_handle),
                operations=[operation],
            )
        )
